def height(root): 
    if root is None: 
        return 0 
    else: 
        # Compute the depth of each subtree 
        left_depth = height(root.left) 
        right_depth = height(root.right) 
        #  Use the larger one 
        return max(left_depth, right_depth) + 1

public static boolean containsDuplicates(int[] arr) {

